/* Context-aware transitions and live, role-scoped monitoring. */
function opportunityOutcome(stage){return ({process:'Aktif',won:'Won',lost:'Lost',cancelled:'Cancelled'})[stage?.type]||'Aktif'}
function stageReasonNames(type){
 const legacyCancel=['Kebutuhan ditunda','Kebutuhan ditarik','Salah input'];
 const legacyLost=['Tidak berminat','Memilih penyedia lain'];
 return activeMaster('reasons').filter(r=>!r.outcome||r.outcome==='all'||r.outcome===type).filter(r=>r.outcome || (type==='cancelled' ? !legacyLost.includes(r.name) : !legacyCancel.includes(r.name))).map(r=>r.name);
}
function stageChangeFields(s){
 if(!s)return '';
 const negative=['lost','cancelled'].includes(s.type),won=s.type==='won';
 let names=negative?stageReasonNames(s.type):[];
 return '<p class="transition-hint">'+(won?'Catat hasil kesepakatan yang berhasil. Kategori alasan penolakan tidak diperlukan.':negative?'Pilih alasan '+(s.type==='lost'?'gagal':'pembatalan')+' dan jelaskan konteksnya.':'Catat perkembangan tahap jika diperlukan. Tidak ada alasan penutupan untuk tahap proses.')+'</p>'+(negative?'<label>Kategori alasan '+(s.type==='lost'?'gagal':'pembatalan')+'<select name="reasonCode" required><option value="">Pilih kategori alasan</option>'+names.map(n=>'<option value="'+E(n)+'">'+E(n)+'</option>').join('')+'</select></label>':'')+area(won?'Ringkasan hasil / bukti keberhasilan':negative?'Detail alasan':'Catatan progres (opsional)','reason','',won||negative)+field(won?'Referensi kesepakatan (jika ada)':'Referensi (jika ada)','reference')+(s.type!=='process'?'<p class="hint">Task yang masih terbuka pada Opportunity ini akan dibatalkan dan tetap tersimpan dalam riwayat.</p>':'');
}
function updateStageChangeFields(){const f=document.querySelector('#form'),s=stageDefs().find(s=>s.id===f.elements.stageId.value);document.querySelector('#stageChangeFields').innerHTML=stageChangeFields(s);document.querySelector('#formerror').textContent=''}
changeStage=function(id){
 const o=opp(id);if(!o||!mine(o))return toast('Opportunity tidak tersedia.');
 const defs=stageDefs().filter(s=>s.active||s.id===o.stageId||s.name===o.stage),current=defs.find(s=>s.id===o.stageId)||defs.find(s=>s.name===o.stage)||defs[0];
 modal('Ubah tahap Opportunity','<label>Tahap<select name="stageId" onchange="updateStageChangeFields()">'+defs.map(s=>'<option value="'+E(s.id)+'" '+(s===current?'selected':'')+'>'+E(s.name)+'</option>').join('')+'</select></label><div id="stageChangeFields">'+stageChangeFields(current)+'</div>',f=>{
 const s=stageDefs().find(s=>s.id===f.stageId);if(!s||(!s.active&&s.id!==o.stageId&&s.name!==o.stage))throw Error('Pilih tahap aktif.');
 const negative=['lost','cancelled'].includes(s.type),reason=String(f.reason||'').trim();
 if(negative&&!stageReasonNames(s.type).includes(f.reasonCode))throw Error('Pilih kategori alasan yang sesuai.');
 if(s.type!=='process'&&!reason)throw Error(s.type==='won'?'Isi ringkasan hasil keberhasilan.':'Isi detail alasan.');
 const old=o.stage;
 if(s.type!=='process'){
 if(o.outcome==='Aktif')o.lastProcessStage=o.stage;
 db.tasks.filter(t=>t.opp===id&&isOpen(t)).forEach(t=>{t.status='Dibatalkan';t.cancelReason='Opportunity '+s.name+': '+reason});o.closed=now();
 }else delete o.closed;
 Object.assign(o,{stage:s.name,stageId:s.id,outcome:opportunityOutcome(s),reason,reasonCode:negative?f.reasonCode:'',reference:String(f.reference||'').trim(),slaDays:Number(s.sla),entered:now()});
 record('Ubah tahap Opportunity',id,old+' → '+s.name+(reason?' / '+reason:''));
 });
};
closeOpp=changeStage;
/* The shared master remains editable; optional scope applies to new and existing items. */
const operationsMasterForm=masterForm;
masterForm=function(id=''){
 if(configTab!=='reasons')return operationsMasterForm(id);
 const r=masters().reasons.find(r=>r.id===id)||{};
 modal(id?'Edit alasan penutupan':'Tambah alasan penutupan',field('Nama','name',r.name||'','text',true)+baseSelect('Status','status',['Aktif','Nonaktif'],r.active===false?'Nonaktif':'Aktif')+baseSelect('Digunakan untuk','reasonOutcome',['Gagal & Dibatalkan','Gagal','Dibatalkan'],({lost:'Gagal',cancelled:'Dibatalkan'})[r.outcome]||'Gagal & Dibatalkan')+'<p class="hint">Kategori ini hanya digunakan untuk penutupan gagal atau pembatalan, bukan keberhasilan.</p>',f=>{
 const cfg=clone(db.config),item={...r,id:r.id||uid('reasons'),name:f.name.trim(),active:f.status==='Aktif',outcome:({'Gagal':'lost','Dibatalkan':'cancelled'})[f.reasonOutcome]||'all'};
 if(!item.name)throw Error('Isi nama alasan.');const i=cfg.masters.reasons.findIndex(r=>r.id===id);if(i<0)cfg.masters.reasons.push(item);else cfg.masters.reasons[i]=item;saveMasters(cfg);
 });
};
/* Dependent controls do not submit stale, hidden values. */
const operationsModal=modal;
modal=function(title,html,handler){operationsModal(title,html,handler);const form=document.querySelector('#form');if(!form)return;
 const type=form.elements.type;
 if(type&&form.elements.participants&&form.elements.meetingAgenda){const update=()=>{const meeting=activityKind(type.value)==='Meeting';for(const name of ['participants','meetingAgenda']){const n=form.elements[name];n.closest('label').hidden=!meeting;n.disabled=!meeting;}};type.addEventListener('change',update);update()}
 const follow=form.elements.follow;
 if(follow){const update=()=>{const mode=follow.value,none=mode==='Tidak ada - perlu penutupan',taskMode=mode==='Tambah Task';for(const name of ['purpose','type','scheduled','due']){const n=form.elements[name];if(!n)continue;const show=!none&&(name!=='type'&&name!=='due'||taskMode);n.closest('label').hidden=!show;n.disabled=!show;} };follow.addEventListener('change',update);update()}
 if(/Review koreksi Nasabah/.test(title)&&form.elements.decision){const n=form.elements.note,update=()=>{const accepted=form.elements.decision.value==='Disetujui';n.required=!accepted;n.closest('label').firstChild.textContent=accepted?'Catatan persetujuan (opsional)':'Alasan penolakan / pengembalian';};form.elements.decision.addEventListener('change',update);update()}

};
const operationsReviewCorrection=reviewCorrection;
reviewCorrection=function(id,decision){operationsReviewCorrection(id,decision);const f=document.querySelector('#form');if(f?.elements.note&&!f.elements.decision){f.elements.note.required=decision!=='Disetujui';f.elements.note.closest('label').firstChild.textContent=decision==='Disetujui'?'Catatan persetujuan (opsional)':'Alasan pengembalian';}};
let dashboardOwner='',dashboardRange='30',dashboardPriority='overdue',dashboardDetail=null,dashboardPage=1;
const DASH_DAY=86400000;
function dashboardDay(value){if(!value)return '';const d=parseCRMDate(value);return Number.isNaN(+d)?'':new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Makassar',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function dashboardStart(){const d=demoToday();if(dashboardRange==='all')return '';if(dashboardRange==='month')return d.slice(0,7)+'-01';const date=new Date(d+'T12:00:00+08:00');date.setTime(+date-(Number(dashboardRange)-1)*DASH_DAY);return dashboardDay(date.toISOString())}
function dashboardInPeriod(date){const d=dashboardDay(date);return !!d&&(!dashboardStart()||d>=dashboardStart())&&d<=demoToday()}
function dashboardScoped(rows){return rows.filter(x=>mine(x)&&(!dashboardOwner||x.owner===dashboardOwner))}
function dashboardModel(){
 const opps=dashboardScoped(db.opps),tasks=dashboardScoped(db.tasks),leads=dashboardScoped(db.leads),customers=dashboardScoped(db.profiles).filter(p=>p.relation==='Customer'),activities=dashboardScoped(db.activities),active=opps.filter(o=>o.outcome==='Aktif'),closed=opps.filter(o=>o.outcome!=='Aktif'&&dashboardInPeriod(o.closed||o.entered));
 const won=closed.filter(o=>o.outcome==='Won'),lost=closed.filter(o=>o.outcome==='Lost'),cancelled=closed.filter(o=>o.outcome==='Cancelled'),over=tasks.filter(overdue),noNext=active.filter(o=>!hasNext(o)),sla=active.filter(overSla),approvals=pendingApprovals().filter(t=>!dashboardOwner||t.owner===dashboardOwner),newLeads=leads.filter(l=>dashboardInPeriod(l.created)),done=tasks.filter(t=>t.status==='Selesai'&&dashboardInPeriod(activities.find(a=>a.task===t.id)?.occurred||t.checkout||t.scheduled));
 return {opps,tasks,leads,customers,activities,active,closed,won,lost,cancelled,over,noNext,sla,approvals,newLeads,done,value:active.reduce((n,o)=>n+(Number(o.value)||0),0),winRate:won.length+lost.length?Math.round(won.length/(won.length+lost.length)*100):null};
}
function dashboardFilter(key,value){if(key==='owner')dashboardOwner=value;if(key==='range')dashboardRange=value;if(key==='priority')dashboardPriority=value;renderContent()}
function dashboardAction(label,action,extra=''){return '<button class="dash-link '+extra+'" onclick="'+E(action)+'">'+label+'<span aria-hidden="true">↗</span></button>'}
function dashboardCompactMoney(value){const n=Number(value)||0;const unit=n>=1e12?[1e12,'triliun']:n>=1e9?[1e9,'miliar']:n>=1e6?[1e6,'juta']:null;return unit?'Rp '+new Intl.NumberFormat('id-ID',{maximumFractionDigits:2}).format(n/unit[0])+' '+unit[1]:rup(n)}
function dashboardMetric(label,value,sub,kind,tone=''){return '<button class="dash-kpi '+tone+'" onclick="dashboardOpen('+E(JSON.stringify(kind))+')"><span>'+E(label)+'</span><strong>'+E(value)+'</strong><small>'+E(sub)+' <span aria-hidden="true">↗</span></small></button>'}
function dashboardRow(x,kind){const isTask=kind==='task',lead=kind==='lead',customer=kind==='customer';const title=isTask?x.purpose:lead?pname(x.profile):customer?x.name:x.name;const route=isTask?'Aktivitas detail':lead?'Lead detail':customer?'Nasabah detail':'Opportunity detail';const label=customer?(x.customerStatus||'Aktif'):isTask?(overdue(x)?'Overdue':x.status):lead?leadLifecycle(x):x.stage;
 return dashboardAction('<span><b>'+E(title)+'</b><small>'+E(x.owner||'AO belum ditentukan')+' · '+E(isTask?fmt(x.due):customer?'Customer 360':lead?x.source:rup(x.value))+'</small></span><em>'+E(label)+'</em>','dashboardNavigate('+JSON.stringify(route)+','+JSON.stringify(x.id)+')');
}
function dashboardNavigate(route,id){document.querySelector('#modal')?.close();go(route,id)}
function dashboardRecords(kind,arg){const m=dashboardModel();const map={active:['Opportunity aktif',m.active,'opp'],value:['Nominal pipeline aktif',m.active,'opp'],leads:['Lead baru pada periode',m.newLeads,'lead'],customers:['Customer aktif',m.customers.filter(p=>(p.customerStatus||'Aktif')==='Aktif'),'customer'],won:['Opportunity berhasil pada periode',m.won,'opp'],lost:['Opportunity gagal pada periode',m.lost,'opp'],cancelled:['Opportunity dibatalkan pada periode',m.cancelled,'opp'],overdue:['Task overdue saat ini',m.over,'task'],noNext:['Opportunity tanpa tindak lanjut',m.noNext,'opp'],sla:['Opportunity melewati SLA',m.sla,'opp'],approvals:['Kunjungan menunggu persetujuan',m.approvals,'task'],done:['Task selesai pada periode',m.done,'task']};
 if(kind==='stage'){const s=stageDefs().find(s=>s.id===arg);return [s?.name||'Tahap',m.active.filter(o=>o.stageId===arg||o.stage===s?.name),'opp']}
 if(kind==='source')return ['Lead baru · '+arg,m.newLeads.filter(l=>l.source===arg),'lead'];
 if(kind==='owner')return ['Opportunity aktif · '+arg,m.active.filter(o=>o.owner===arg),'opp'];
 if(kind==='day')return ['Aktivitas · '+arg,m.activities.filter(a=>dashboardDay(a.occurred)===arg),'activity'];
 return map[kind]||map.active;
}
function dashboardOpen(kind,arg=''){dashboardDetail={kind,arg};dashboardPage=1;dashboardRenderDetail()}
function dashboardRenderDetail(){const [title,rows,kind]=dashboardRecords(dashboardDetail.kind,dashboardDetail.arg),count=rows.length,pages=Math.max(1,Math.ceil(count/10));dashboardPage=Math.min(pages,Math.max(1,dashboardPage));
 modal(E(title),'<p class="hint">'+count+' data · '+E(dashboardOwner||'Seluruh AO dalam akses Anda')+'</p><div class="dash-detail">'+(rows.slice((dashboardPage-1)*10,dashboardPage*10).map(x=>kind==='activity'?dashboardAction('<span><b>'+E(pname(x.profile))+'</b><small>'+E(x.type)+' · '+E(x.result)+' · '+E(fmt(x.occurred))+'</small></span>','dashboardNavigate('+JSON.stringify(x.task?'Aktivitas detail':x.opp?'Opportunity detail':x.lead?'Lead detail':'Nasabah detail')+','+JSON.stringify(x.task||x.opp||x.lead||x.profile)+')'):dashboardRow(x,kind)).join('')||empty('Belum ada data pada pilihan ini.'))+'</div><div class="dash-pagination"><button type="button" '+(dashboardPage===1?'disabled':'')+' onclick="dashboardPage--;dashboardRenderDetail()">Sebelumnya</button><span>'+dashboardPage+' / '+pages+'</span><button type="button" '+(dashboardPage===pages?'disabled':'')+' onclick="dashboardPage++;dashboardRenderDetail()">Berikutnya</button></div>',()=>{});document.querySelector('#form>.actions:last-child')?.remove();document.querySelector('#form').querySelectorAll('.dash-link').forEach(b=>b.type='button');document.querySelector('#form').onsubmit=e=>e.preventDefault();
}
function comprehensiveDashboard(){
 const m=dashboardModel(),period=dashboardRange==='all'?'Seluruh periode tercatat':dashboardStart()+' — '+demoToday(),priorities={overdue:['Task overdue',m.over,'task'],noNext:['Tanpa tindak lanjut',m.noNext,'opp'],sla:['Melewati SLA',m.sla,'opp'],approvals:['Menunggu persetujuan',m.approvals,'task']},[priorityTitle,priorityRows,priorityKind]=priorities[dashboardPriority];
 const stageRows=stageDefs().filter(s=>s.type==='process'&&(s.active||m.active.some(o=>o.stageId===s.id||o.stage===s.name))).map(s=>({...s,rows:m.active.filter(o=>o.stageId===s.id||o.stage===s.name)})),maxStage=Math.max(1,...stageRows.map(s=>s.rows.length));
 const aoNames=[...new Set([...m.opps,...m.tasks,...m.leads].map(x=>x.owner).filter(Boolean))];
 const ownerOptions=[...new Set([...db.opps,...db.tasks,...db.leads].filter(mine).map(x=>x.owner).filter(Boolean))];
 const sources=[...new Set(m.newLeads.map(l=>l.source||'Belum diisi'))];
 const days=Array.from({length:7},(_,i)=>dashboardDay(new Date(Date.now()-(6-i)*DASH_DAY).toISOString())),dayCounts=days.map(d=>m.activities.filter(a=>dashboardDay(a.occurred)===d).length),maxDay=Math.max(1,...dayCounts);
 return '<div class="dashboard-v2"><section class="dash-hero"><div><span class="dash-eyebrow">MONITORING RELASI & PENJUALAN</span><h1>Ringkasan kinerja dan prioritas</h1><p>Pahami posisi pipeline, hasil kerja, dan tindak lanjut tim dalam satu tampilan.</p></div><div class="actions">'+btn('Buat Task','newTask()',true)+btn('Buat Opportunity','newOpp()')+'</div></section><div class="dash-filters"><label>Penanggung jawab<select aria-label="Filter AO dashboard" onchange="dashboardFilter(\'owner\',this.value)"><option value="">Seluruh AO dalam akses saya</option>'+ownerOptions.map(n=>'<option '+(n===dashboardOwner?'selected':'')+' value="'+E(n)+'">'+E(n)+'</option>').join('')+'</select></label><label>Periode hasil & aktivitas<select aria-label="Periode dashboard" onchange="dashboardFilter(\'range\',this.value)">'+[['7','7 hari terakhir'],['30','30 hari terakhir'],['month','Bulan ini'],['all','Seluruh periode']].map(([v,n])=>'<option value="'+v+'" '+(v===dashboardRange?'selected':'')+'>'+n+'</option>').join('')+'</select></label><button onclick="dashboardOwner=\'\';dashboardRange=\'30\';renderContent()">Reset filter</button><span>Data terbaru · WITA<br><small>'+E(fmt(now()))+'</small></span></div><div class="dash-section-title"><h2>Posisi saat ini</h2><small>Snapshot seluruh data sesuai akses dan AO; tidak dibatasi periode.</small></div><div class="dash-kpis">'+dashboardMetric('Opportunity aktif',m.active.length,'Peluang yang masih diproses','active')+dashboardMetric('Nominal pipeline',dashboardCompactMoney(m.value),rup(m.value)+' · nilai indikatif','value')+dashboardMetric('Task overdue',m.over.length,'Melewati deadline dan belum selesai','overdue',m.over.length?'is-danger':'')+dashboardMetric('Customer aktif',m.customers.filter(p=>(p.customerStatus||'Aktif')==='Aktif').length,'Customer 360 berstatus aktif','customers')+'</div><div class="dash-section-title"><h2>Hasil pada periode</h2><small>'+E(period)+'</small></div><div class="dash-kpis">'+dashboardMetric('Lead baru',m.newLeads.length,'Berdasarkan tanggal lead dibuat','leads')+dashboardMetric('Opportunity berhasil',m.won.length,rup(m.won.reduce((n,o)=>n+(Number(o.value)||0),0))+' nilai indikatif','won','is-success')+dashboardMetric('Win rate',m.winRate===null?'—':m.winRate+'%',m.won.length+' berhasil / '+(m.won.length+m.lost.length)+' berhasil + gagal','won')+dashboardMetric('Task selesai',m.done.length,'Tanggal hasil; jadwal jika belum ada hasil','done')+'</div><div class="dash-grid"><section class="dash-panel"><div class="dash-panel-head"><div><h2>Pipeline aktif per tahap</h2><p>Klik tahap untuk melihat Opportunity dan nominalnya.</p></div><span class="dash-counter">'+m.active.length+' aktif</span></div><div class="dash-stage-list">'+(stageRows.map(s=>'<button class="dash-stage" onclick="dashboardOpen(\'stage\','+E(JSON.stringify(s.id))+')"><span><b>'+E(s.name)+'</b><small>'+s.rows.length+' Opportunity · '+rup(s.rows.reduce((n,o)=>n+(Number(o.value)||0),0))+'</small></span><span class="dash-track"><i style="width:'+(s.rows.length/maxStage*100)+'%"></i></span><strong>'+s.rows.length+'</strong></button>').join('')||empty('Tahap proses belum dikonfigurasi.'))+'</div><p class="dash-footnote">Nominal lintas produk adalah potensi bisnis indikatif; bukan realisasi pendapatan Bank.</p></section><section class="dash-panel"><div class="dash-panel-head"><div><h2>Hasil closing</h2><p>Menurut tanggal penutupan pada periode terpilih.</p></div></div><div class="dash-outcomes">'+[['Berhasil','won',m.won,'success'],['Gagal','lost',m.lost,'danger'],['Dibatalkan','cancelled',m.cancelled,'neutral']].map(([n,k,rows,c])=>'<button class="dash-outcome '+c+'" onclick="dashboardOpen(\''+k+'\')"><span>'+n+'</span><strong>'+rows.length+'</strong><small>'+rup(rows.reduce((n,o)=>n+(Number(o.value)||0),0))+'</small></button>').join('')+'</div><p class="dash-footnote">Win rate = berhasil ÷ (berhasil + gagal). Pembatalan tidak masuk perhitungan. “—” berarti belum ada hasil.</p><h3>Sumber lead baru</h3>'+ (sources.map(source=>dashboardAction('<span>'+E(source)+'</span><b>'+m.newLeads.filter(l=>(l.source||'Belum diisi')===source).length+'</b>','dashboardOpen(\'source\','+JSON.stringify(source)+')')).join('')||empty('Belum ada lead baru pada periode ini.'))+'</section></div><section class="dash-panel"><div class="dash-panel-head"><div><h2>Prioritas tindak lanjut</h2><p>Masalah aktif saat ini, urutkan tindakan sebelum menambah peluang baru.</p></div>'+btn('Buka persetujuan',"go('Persetujuan')")+'</div><div class="dash-tabs" role="group" aria-label="Kategori prioritas">'+Object.entries(priorities).map(([key,[name,rows]])=>'<button aria-pressed="'+(dashboardPriority===key)+'" onclick="dashboardFilter(\'priority\',\''+key+'\')">'+name+' <b>'+rows.length+'</b></button>').join('')+'</div><div class="dash-priority">'+(priorityRows.slice().sort((a,b)=>priorityKind==='task'?sortPriority(a,b):age(b)-age(a)).slice(0,5).map(x=>dashboardRow(x,priorityKind)).join('')||empty('Tidak ada '+priorityTitle.toLowerCase()+'.'))+'</div>'+dashboardAction('Lihat seluruh '+E(priorityTitle.toLowerCase()),'dashboardOpen('+JSON.stringify(dashboardPriority)+')')+'</section><div class="dash-grid"><section class="dash-panel"><div class="dash-panel-head"><div><h2>Beban kerja AO</h2><p>Posisi aktif saat ini. Klik AO untuk membuka pipeline miliknya.</p></div></div><div class="scrolltable"><table class="dash-table"><thead><tr><th>AO</th><th>Opportunity aktif</th><th>Nominal pipeline</th><th>Task terbuka</th><th>Overdue</th></tr></thead><tbody>'+aoNames.map(owner=>{const os=m.active.filter(o=>o.owner===owner),ts=m.tasks.filter(t=>t.owner===owner&&isOpen(t));return '<tr><td><button class="dash-owner" onclick="dashboardOpen(\'owner\','+E(JSON.stringify(owner))+')">'+E(owner)+' ↗</button></td><td>'+os.length+'</td><td>'+rup(os.reduce((n,o)=>n+(Number(o.value)||0),0))+'</td><td>'+ts.length+'</td><td>'+ts.filter(overdue).length+'</td></tr>'}).join('')+'</tbody></table></div>'+(aoNames.length?'':empty('Belum ada data AO.'))+'</section><section class="dash-panel"><div class="dash-panel-head"><div><h2>Aktivitas 7 hari terakhir</h2><p>Hasil aktivitas yang dicatat; klik batang untuk detail. Filter AO tetap berlaku.</p></div></div><div class="dash-chart">'+days.map((d,i)=>'<button aria-label="'+E(d)+': '+dayCounts[i]+' aktivitas" onclick="dashboardOpen(\'day\',\''+d+'\')"><b>'+dayCounts[i]+'</b><span class="dash-chart-bar"><i style="height:'+(dayCounts[i]/maxDay*100)+'%"></i></span><small>'+new Date(d+'T12:00:00+08:00').toLocaleDateString('id-ID',{timeZone:'Asia/Makassar',day:'numeric',month:'short'})+'</small></button>').join('')+'</div></section></div><p class="dash-footnote">Data CRM sesuai kewenangan akun. Pipeline mengikuti master tahap terbaru. Angka bukan data Core Banking atau keputusan kredit otomatis.</p></div>';
}
const operationsRenderContent=renderContent;
renderContent=function(){if(view==='Monitoring'&&(authUser||journey)){document.querySelector('#app').innerHTML=comprehensiveDashboard();return}return operationsRenderContent()};
